    function organizePanelSections(panel){
        const tab=name=>panel.querySelector(`[data-tab-panel="${name}"]`);
        const header=(section,title)=>{const h=Array.from(section?.querySelectorAll('.mb-section-title')||[]).find(h=>h.textContent.trim()===title);return h;};
        const moveToBottom=(name,title)=>{const host=tab(name);for(const s of host?.querySelectorAll(':scope > .mb-section')||[])if(header(s,title))host.append(s);};
        moveToBottom('resupply','Inventory Browser');moveToBottom('diagnostics','Server Loot Routing');
        const inventorySection=Array.from(tab('resupply')?.querySelectorAll(':scope > .mb-section')||[]).find(s=>header(s,'Inventory Browser'));
        if(inventorySection&&!inventorySection.querySelector(':scope > details')){
            const heading=header(inventorySection,'Inventory Browser'),details=document.createElement('details'),summary=document.createElement('summary');
            details.className='mb-resupply-fold';summary.className=heading.className;summary.append(...Array.from(heading.childNodes));heading.remove();
            details.append(summary,...Array.from(inventorySection.childNodes));inventorySection.append(details);inventorySection.classList.add('mb-resupply-inventory');
        }

        const utility=tab("utility");

        const targeting=tab('targeting'),core=panel.querySelector('#minibia-bot-auto-attack-enabled')?.closest('.mb-section');
        const extract=id=>{const toggle=panel.querySelector(id),h=toggle?.closest('.mb-section-title'),section=h?.parentElement;if(!section||!targeting)return null;section.classList.add('mb-section');section.style.cssText='';h.classList.remove('mb-section-title--sub');h.style.cssText='';targeting.append(section);return section;};
        const rune=extract('#minibia-bot-rune-shooter-enabled');
        const listsTitle=Array.from(targeting?.querySelectorAll('.mb-section-title')||[]).find(h=>h.textContent.trim()==='Target Lists');
        const lists=listsTitle?.parentElement;if(lists){lists.classList.add('mb-section');lists.style.cssText='';listsTitle.classList.remove('mb-section-title--sub');listsTitle.style.cssText='';targeting.append(lists);}
        const rules=targeting?.querySelector('.mb-combat-rules');if(core)targeting.prepend(core);if(rune)targeting.append(rune);if(rules)targeting.append(rules);if(lists)targeting.append(lists);
        const cave=tab('cave');for(const title of ['Recovery Safety','Debug']){const h=Array.from(cave?.querySelectorAll('.mb-section-title')||[]).find(h=>h.textContent.trim()===title);const body=h?.parentElement;if(!body||body.tagName==='DETAILS')continue;const details=document.createElement('details');details.className='mb-cave-details';const summary=document.createElement('summary');summary.className='mb-section-title mb-section-title--sub';const label=document.createElement('span');label.className='mb-title-text';label.textContent=title;summary.append(label);details.append(summary);body.replaceWith(details);h.remove();details.append(...Array.from(body.childNodes));}
        for(const title of ['Waypoint Properties']){
            const h=Array.from(cave?.querySelectorAll('.mb-section-title')||[]).find(h=>h.textContent.trim()===title);
            const body=h?.parentElement;if(!body||body.tagName==='DETAILS'||body.querySelector(':scope > details'))continue;
            const details=document.createElement('details');details.className='mb-cave-fold';
            const summary=document.createElement('summary');summary.className=h.className;summary.style.cssText='cursor:pointer;display:list-item;margin-bottom:6px';
            summary.append(...Array.from(h.childNodes));h.remove();
            details.append(summary,...Array.from(body.childNodes));body.append(details);
        }
        panel.querySelectorAll('[data-client-extras]').forEach(s=>s.classList.add('mb-new-section'));
        const style=document.createElement('style');style.textContent=`
#minibia-bot-panel .mb-new-section{color:var(--mb-hub-text-2,#cfc8b8);font-size:11px;}
#minibia-bot-panel .mb-new-section .mb-small-note{color:var(--mb-hub-muted,#a39d90);}
#minibia-bot-panel .mb-cave-fold>summary{cursor:pointer;display:list-item!important;}
#minibia-bot-panel .mb-status-grid{gap:5px!important;}
#minibia-bot-panel .mb-status-card{display:grid!important;grid-template-columns:minmax(0,1fr) auto;gap:3px 6px!important;padding:6px!important;}
#minibia-bot-panel .mb-status-card-top{gap:5px!important;}
#minibia-bot-panel .mb-status-card-icon{width:22px!important;height:22px!important;font-size:13px!important;border-radius:3px!important;}
#minibia-bot-panel .mb-status-card-state{grid-column:1;font-size:9px;gap:4px!important;margin:0!important;}
#minibia-bot-panel .mb-status-toggle{grid-column:2;grid-row:1/3;align-self:center;width:auto!important;padding:3px 7px!important;font-size:10px!important;margin:0!important;}
#minibia-bot-panel .mb-cave-details{border-top:1px solid rgba(255,255,255,.08);margin-top:10px;padding-top:6px;}
#minibia-bot-panel .mb-cave-details>summary{cursor:pointer;display:list-item;}
`;panel.append(style);
    }

    const panelPositionKey = "minibiaBot.ui.panelPosition";
    const panelCollapsedKey = "minibiaBot.ui.panelCollapsed";

    // ---- UTILITY FUNCTIONS ----
    function destroy() {
        volumeControlCleanup?.(); volumeControlCleanup = null;
        worldMapEditor?.destroy();
        worldMapEditor = null;
        document.getElementById("minibia-bot-panel")?.remove();
        document.getElementById("minibia-bot-style")?.remove();
    }

    function parsePreferredTargetNames(value) {
        if (!value)
            return [];
        // Split by newline, or by comma if no newline
        let parts;
        if (value.includes('\n')) {
            parts = value.split(/\n/);
        } else {
            parts = value.split(/,/);
        }
        return parts
        .map(s => s.trim())
        .filter(Boolean)
        .filter((name, idx, arr) =>
            arr.findIndex(o => o.toLowerCase() === name.toLowerCase()) === idx);
    }
    
    // Move each section's enable toggle up next to its header label.
// Convention: the toggle's checkbox id ends in "-enabled" or "-toggle".
function findSectionEnableToggle(section) {
    // Preferred match: a checkbox whose id clearly marks it as the module switch.
    const candidates = section.querySelectorAll('input[type="checkbox"]');
    for (const cb of candidates) {
        if (/(?:-enabled|-toggle)$/.test(cb.id)) {
            const toggle = cb.closest(".mb-toggle");
            if (toggle) return toggle;
        }
    }
    // Fallback: first toggle that is a direct child of the section (or of a direct .mb-stack).
    let toggle = section.querySelector(':scope > .mb-toggle');
    if (toggle) return toggle;
    const stack = section.querySelector(':scope > .mb-stack');
    if (stack) {
        toggle = stack.querySelector(':scope > .mb-toggle');
        if (toggle) return toggle;
    }
    return null;
}

function upgradeSectionHeaders(panel) {
    panel.querySelectorAll(".mb-section").forEach(section => {
        // Don't double-process.
        if (section.dataset.headerUpgraded === "true") return;

        // Header label must be the section's own direct child.
        const label = section.querySelector(':scope > .mb-label');
        if (!label) return;

        const toggle = findSectionEnableToggle(section);
        if (!toggle) return;

        // Preserve accessibility: pull the label text into aria-label since we
        // hide the visible <span> via CSS.
        const checkbox = toggle.querySelector('input[type="checkbox"]');
        if (checkbox && !checkbox.getAttribute("aria-label")) {
            const spanText = toggle.querySelector("span")?.textContent?.trim();
            if (spanText) checkbox.setAttribute("aria-label", spanText);
            else checkbox.setAttribute("aria-label", label.textContent.trim() || "Enable");
        }

        // Build the flex header row.
        const header = document.createElement("div");
        header.className = "mb-section-header";
        label.parentNode.insertBefore(header, label);
        header.appendChild(label);
        header.appendChild(toggle);

        section.dataset.headerUpgraded = "true";
    });
}
    
    // ---- REFRESH FUNCTIONS (tie UI to bot state) ----
    function refreshAutoAttackPriorityStatus(options = {}) {
        const input = document.getElementById("minibia-bot-auto-attack-priority-names");
        const mode = document.getElementById("minibia-bot-auto-attack-priority-match-mode");
        const config = bot.attack?.config || {};
        if (input && (options.force || document.activeElement !== input))
            input.value = (config.targetPriorityNames || []).join("\n");
        if (mode && (options.force || document.activeElement !== mode))
            mode.value = config.targetPriorityMatchMode === "includes" ? "includes" : "exact";
    }

    function saveAutoAttackPriorityConfig() {
        const input = document.getElementById("minibia-bot-auto-attack-priority-names");
        const mode = document.getElementById("minibia-bot-auto-attack-priority-match-mode");
        bot.attack?.updateConfig?.({
            targetPriorityNames: parsePreferredTargetNames(input?.value || ""),
            targetPriorityMatchMode: mode?.value === "includes" ? "includes" : "exact"
        });
        refreshAutoAttackPriorityStatus({ force: true });
    }

    function refreshAutoAttackPreferredStatus(options = {}) {
        refreshAutoAttackPriorityStatus(options);
        const force = options.force === true;
        const input = document.getElementById("minibia-bot-auto-attack-preferred-names");
        const modeSelect = document.getElementById("minibia-bot-auto-attack-preferred-match-mode");
        const statusLabel = document.getElementById("minibia-bot-auto-attack-preferred-status");
        const attackConfig = bot.attack?.status?.().config || bot.attack?.config || {};
        const preferred = Array.isArray(attackConfig.preferredTargetNames) ? attackConfig.preferredTargetNames : [];
        const mode = attackConfig.preferredMatchMode === "includes" ? "includes" : "exact";

        // --- CHANGE: join with newline instead of comma ---
        if (input && (force || document.activeElement !== input)) {
            input.value = preferred.join("\n");
        }

        if (modeSelect && (force || document.activeElement !== modeSelect))
            modeSelect.value = mode;
        if (statusLabel) {
            const names = preferred.length ? preferred.join(", ") : "none";
            const modeText = mode === "includes" ? "contains text" : "exact name";
            statusLabel.textContent = `Preferred mobs: ${names} | Mode: ${modeText}`;
        }
    }

    function refreshAutoAttackIgnoredStatus(options = {}) {
        const force = options.force === true;
        const input = document.getElementById("minibia-bot-auto-attack-ignored-names");
        const statusLabel = document.getElementById("minibia-bot-auto-attack-ignored-status");
        const attackConfig = bot.attack?.status?.().config || bot.attack?.config || {};
        const ignored = Array.isArray(attackConfig.ignoredTargetNames) ? attackConfig.ignoredTargetNames : [];
        const escapeToggle = document.getElementById("minibia-bot-auto-attack-ignored-trap");
        if (escapeToggle) escapeToggle.checked = attackConfig.attackIgnoredWhenTrapped === true;

        // --- CHANGE: join with newline instead of comma ---
        if (input && (force || document.activeElement !== input)) {
            input.value = ignored.join("\n");
        }

        if (statusLabel) {
            statusLabel.textContent = ignored.length ? `Ignored: ${ignored.join(", ")}` : "Ignored: none";
        }
    }

    function refreshAntiBotStatus() {
        const toggle = document.getElementById("minibia-bot-antibot-enabled");
        if (!toggle)
            return;
        const status = bot.antiBotMonitor?.status?.();
        const closeWindowToggle = document.getElementById("minibia-bot-antibot-close-window");
        if (closeWindowToggle) closeWindowToggle.checked = status?.config?.closeWindowOnCheck === true;
        const lastXlog = document.getElementById("minibia-bot-antibot-last-xlog");
        if (lastXlog) {
            lastXlog.hidden = !status?.lastXlogTime;
            lastXlog.textContent = status?.lastXlogTime ? `Last anti-bot XLOG: ${status.lastXlogTime} (local time)` : "";
        }
        if (status) {
            toggle.checked = status.running;
        } else {
            toggle.checked = false;
        }
    }

    // ---- Paladin UI ----
    function refreshPaladinStatus() {
        const toggle = document.getElementById("minibia-bot-paladin-enabled");
        const statusLabel = document.getElementById("minibia-bot-paladin-status");
        const handCountLabel = document.getElementById("minibia-bot-paladin-hand-count");
        const status = bot.paladin?.status?.();

        if (toggle && document.activeElement !== toggle) {
            toggle.checked = !!status?.running;
        }
        if (statusLabel) {
            if (status?.corpseJobActive) {
                statusLabel.textContent =
                    `Status: looting ${status.corpseJobMonster || "corpse"}`;
            } else {
                statusLabel.textContent =
                    status?.running
                        ? "Status: running"
                        : "Status: idle";
            }
        }

        if (handCountLabel) {
            // Get left hand count
            const eq = window.gameClient?.player?.equipment;
            let leftHandCount = 0;
            if (eq) {
                const leftItem = eq.getSlotItem(5); // LEFT_HAND_SLOT
                const weaponId = bot.paladin?.config?.weaponId;
                if (leftItem && leftItem.id === weaponId) {
                    leftHandCount = leftItem.count || 1;
                }
            }
            handCountLabel.textContent = leftHandCount;
        }
    }

    // ---- Looter UI ----
    function refreshLooterStatus() {
        const toggle = document.getElementById("minibia-bot-looter-enabled");
        const statusLabel = document.getElementById("minibia-bot-looter-status");
        const destLabel = document.getElementById("minibia-bot-looter-dest-status");
        const listContainer = document.getElementById("minibia-bot-looter-item-list");
        const walkCorpseToggle =
            document.getElementById("minibia-bot-looter-walk-corpses");
        const corpseDistanceInput =
            document.getElementById("minibia-bot-looter-corpse-distance");

        const status = bot.looter?.status?.();
        const blacklistMode = status?.lootMode === "blacklist";
        const modeInput = document.getElementById("minibia-bot-looter-mode");
        if (modeInput && document.activeElement !== modeInput) modeInput.value = blacklistMode ? "blacklist" : "whitelist";
        const listTitle = document.getElementById("minibia-bot-looter-list-title");
        if (listTitle) listTitle.textContent = blacklistMode ? "Blacklisted Items — Leave or Drop" : "Tracked Items";
        const modeNote = document.getElementById("minibia-bot-looter-mode-note");
        if (modeNote) modeNote.textContent = blacklistMode
            ? 'Loots unlisted items from “dead” containers only. Listed items stay in the corpse unless Drop is checked. Skips all container items and your own bags.'
            : 'Loots listed items from “dead” containers only. Container items and your own bags are never loot sources.';
        if (toggle && document.activeElement !== toggle) {
            toggle.checked = !!status?.running;
        }
        if (statusLabel) {
            statusLabel.textContent = status?.running ? "Status: running" : "Status: idle";
        }
        if (destLabel) {
            const destId = bot.looter?.getDestinationId?.();
            destLabel.textContent = destId ? `Destination: container ${destId}` : "No destination selected";
        }

        if (
            walkCorpseToggle &&
            document.activeElement !== walkCorpseToggle
        ) {
            walkCorpseToggle.checked =
                !!status?.walkToCorpses;
        }

        if (
            corpseDistanceInput &&
            document.activeElement !== corpseDistanceInput
        ) {
            corpseDistanceInput.value =
                status?.corpseMaxDistance ?? 12;
        }

        const corpseStatus = document.getElementById("minibia-bot-corpse-looter-status");
        if (corpseStatus) {
            const phase = status?.corpseJobPhase;
            const detail = status?.corpseJobActive
                ? `${phase === "walking" ? "Walking to" : phase === "opening" ? "Opening" : status.running ? "Looting" : "Native auto-loot:"} ${status.corpseJobMonster || "corpse"}`
                : status?.corpseQueueLength ? `Queued: ${status.corpseQueueLength} · waiting for combat to clear` : "Ready";
            corpseStatus.textContent = status?.walkToCorpses
                ? `${detail} · ${status.corpseLootHandler}` : "Status: off";
        }

        // Render tracked items
        if (listContainer) {
            const items = bot.looter?.getTrackedItems?.() || [];
            listContainer.innerHTML = "";
            if (!items.length) {
                const empty = document.createElement("div");
                empty.className = "mb-small-note";
                empty.textContent = blacklistMode ? "Blacklist empty — all non-container items in corpses will be looted." : "No items tracked.";
                listContainer.appendChild(empty);
            } else {
                for (const [id, name] of items) {
                    const row = document.createElement("div");
                    row.className = "mb-list-row";
                    row.style.cssText = "display:flex;justify-content:space-between;align-items:center;gap:8px;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);";

                    const label = document.createElement("span");
                    label.textContent = String(id).startsWith('legacy:') && !blacklistMode ? `${name} · re-track` : name;
                    label.title = String(id).startsWith('legacy:') ? 'Re-track this item to capture its exact SID.' : `SID ${String(id).split(':')[0]} · CID ${String(id).split(':')[1]} · Fluid ${String(id).split(':')[2]||0}`;
                    label.style.cssText = "flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;";

                    const actions = document.createElement("div");
                    actions.style.cssText = "display:flex;align-items:center;gap:7px;flex:0 0 auto;";

                    const dropLabel = document.createElement("label");
                    dropLabel.className = "mb-toggle";
                    dropLabel.style.cssText = "margin:0;font-size:10px;display:flex;align-items:center;gap:4px;white-space:nowrap;";

                    const dropToggle = document.createElement("input");
                    dropToggle.type = "checkbox";
                    dropToggle.checked =
                        !!bot.looter?.isDropTrackedItem?.(id);
                    dropToggle.title =
                        "Drop this tracked item on your current ground tile instead of moving it to the loot destination.";
                    dropToggle.addEventListener("change", () => {
                        bot.looter?.setTrackedItemDrop?.(
                            id,
                            dropToggle.checked
                        );
                    });

                    const dropText = document.createElement("span");
                    dropText.textContent = "Drop";

                    dropLabel.appendChild(dropToggle);
                    dropLabel.appendChild(dropText);

                    const removeBtn = document.createElement("button");
                    removeBtn.type = "button";
                    removeBtn.className = "mb-small-button";
                    removeBtn.textContent = "✕";
                    removeBtn.title = "Remove tracked item";
                    removeBtn.setAttribute("aria-label","Remove " + name);
                    removeBtn.style.cssText = "width:24px;padding:2px;background:#5a2020;color:#ff8888;border-color:#883030;";
                    removeBtn.addEventListener("click", () => {
                        bot.looter.removeTrackedItem(id);
                        refreshLooterStatus();
                    });

                    actions.appendChild(dropLabel);
                    actions.appendChild(removeBtn);
                    row.appendChild(label);
                    row.appendChild(actions);
                    listContainer.appendChild(row);
                }
            }
        }
    }

    function refreshPinkSkullStatus() {
        const toggle = document.getElementById("minibia-bot-pink-skull-enabled");
        if (toggle)
            toggle.checked = !!bot.pinkSkull?.status?.().running;
    }

    function saveAutoAttackPreferredConfig() {
        const input = document.getElementById("minibia-bot-auto-attack-preferred-names");
        const modeSelect = document.getElementById("minibia-bot-auto-attack-preferred-match-mode");
        const preferred = parsePreferredTargetNames(input?.value || "");
        const mode = modeSelect?.value === "includes" ? "includes" : "exact";
        bot.attack?.updateConfig?.({
            preferredTargetNames: preferred,
            preferredMatchMode: mode
        });
        refreshAutoAttackPreferredStatus({
            force: true
        });
        bot.log?.("auto attack preferred targets updated", {
            preferredTargetNames: preferred,
            preferredMatchMode: mode
        });
    }

    function saveAutoAttackIgnoredConfig() {
        const input = document.getElementById("minibia-bot-auto-attack-ignored-names");
        const ignored = parsePreferredTargetNames(input?.value || ""); // Reuse the existing parser
        bot.attack?.updateConfig?.({
            ignoredTargetNames: ignored
        });
        refreshAutoAttackIgnoredStatus({
            force: true
        });
        bot.log?.("auto attack ignored targets updated", {
            ignoredTargetNames: ignored
        });
    }

    // ---- HEAL UI ----
    let healEditIndex = null;

    function setHealRuleError(message = "") {
        const error = document.getElementById("minibia-bot-heal-rule-error");
        if (error) { error.textContent = message; error.hidden = !message; }
        if (message) bot.log(message);
    }

    function refreshHealRuleFields() {
        const source = document.getElementById("minibia-bot-heal-source")?.value || "hotbar";
        for (const mode of ["hotbar", "spell", "item"]) {
            const group = document.getElementById(`minibia-bot-heal-${mode}-fields`);
            if (group) { group.hidden = source !== mode; group.style.display = source === mode ? "grid" : "none"; }
        }
        const paralyzeOptions = document.getElementById("minibia-bot-heal-paralyze-options");
        if (paralyzeOptions) paralyzeOptions.hidden = document.getElementById("minibia-bot-heal-condition")?.value !== "paralyzed";
        setHealRuleError();
    }

    function refreshHealSpellChoices() {
        const list = document.getElementById("minibia-bot-heal-spell-choices");
        if (!list) return;
        list.replaceChildren();
        const spells = window.gameClient?.interface?.SPELLS;
        if (!spells || typeof spells[Symbol.iterator] !== "function") return;
        for (const [, spell] of spells) {
            if (!spell?.words) continue;
            const option = document.createElement("option");
            option.value = spell.words;
            option.label = `${spell.name || spell.words} (${Number(spell.mana) || 0} MP)`;
            list.appendChild(option);
        }
    }

    function getHealRuleFormValues() {
        const value = id => document.getElementById(`minibia-bot-heal-${id}`)?.value ?? "";
        const number = id => String(value(id)).trim() ? Number(value(id)) : NaN;
        const source = value("source") || "hotbar";
        return {
            source,condition:value("condition")==='paralyzed'?'paralyzed':'always',
            skipWhileTargeting: value("condition") === "paralyzed" && document.getElementById("minibia-bot-heal-skip-target")?.checked === true,
            slot: number("slot"),
            spellWords: source === "spell" ? String(value("spell")).trim() : "",
            manaCost: source === "spell" ? number("manacost") : 0,
            item: source === "item" ? value("item") : "",
            minHp: number("minhp"), maxHp: number("maxhp"),
            minMana: number("minmana"), maxMana: number("maxmana"),
        };
    }

    function setHealRuleFormValues(rule) {
        const normalized = bot.heal.normalizeRule(rule);
        document.getElementById("minibia-bot-heal-source").value = normalized.source;
        document.getElementById("minibia-bot-heal-condition").value = normalized.condition||"always";
        document.getElementById("minibia-bot-heal-skip-target").checked = normalized.skipWhileTargeting;
        document.getElementById("minibia-bot-heal-slot").value = normalized.slot;
        document.getElementById("minibia-bot-heal-spell").value = normalized.spellWords;
        document.getElementById("minibia-bot-heal-manacost").value = normalized.manaCost;
        document.getElementById("minibia-bot-heal-item").value = normalized.item || "ih";
        for (const [id, key] of [["minhp", "minHpPercent"], ["maxhp", "maxHpPercent"], ["minmana", "minManaPercent"], ["maxmana", "maxManaPercent"]])
            document.getElementById(`minibia-bot-heal-${id}`).value = normalized[key];
        refreshHealSpellChoices();
        refreshHealRuleFields();
    }

    function clearHealRuleForm() {
        const editor=document.getElementById("minibia-bot-heal-editor");
        if(editor)editor.hidden=true;
        setHealRuleFormValues({ source: "hotbar", slot: 1 });
        document.getElementById("minibia-bot-heal-save").textContent = "Add Rule";
        healEditIndex = null;
    }

    function refreshHealRules() {
        const list = document.getElementById("minibia-bot-heal-rules-list");
        if (!list) return;
        const rules = bot.heal?.config?.healRules || [];
        list.replaceChildren();
        if (!rules.length) {
            const empty = document.createElement("div");
            empty.className = "mb-small-note"; empty.textContent = "No heal rules configured.";
            list.appendChild(empty); return;
        }
        rules.forEach((rule, index) => {
            const row = document.createElement("div");
            row.className = "mb-list-row";
            row.style.cssText = "display:grid;grid-template-columns:14px minmax(0,1fr) auto auto;gap:6px;align-items:center;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.08);";
            const enabled=document.createElement("input");
            enabled.type="checkbox";enabled.checked=rule.enabled!==false;
            enabled.style.cssText="width:14px;min-width:14px;margin:0;";
            enabled.setAttribute("aria-label",`Enable healing rule ${index+1}`);
            enabled.addEventListener("change",()=>{
                const current=bot.heal.config.healRules.map((r,i)=>i===index?{...r,enabled:enabled.checked}:r);
                bot.heal.updateConfig({healRules:current});refreshHealRules();
            });row.appendChild(enabled);
            const info = document.createElement("div");
            info.style.cssText = "display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:11px;min-width:0;";
            if(rule.enabled===false)info.style.opacity="0.45";
            const label = document.createElement("span"), source = bot.heal.getRuleSource(rule);
            if (source === "hotbar") label.textContent = `Hotbar Slot ${rule.slot}`;
            else if (source === "item") label.textContent = bot.heal.itemTypes[rule.item]?.label || "Choose an item";
            else {
                const spell = bot.heal.resolveSpell(rule.spellWords);
                label.textContent = `${spell.name ? spell.name + " · " : ""}${spell.words} (${rule.manaCost} MP)`;
            }
            if(rule.condition==='paralyzed')label.textContent='🧊 Paralyzed · '+(rule.skipWhileTargeting?'No target · ':'')+label.textContent;
            label.style.cssText = "font-weight:bold;color:#d4c48a;";
            info.appendChild(label);
            const hp = document.createElement("span");
            hp.textContent = `HP ${rule.minHpPercent}‑${rule.maxHpPercent}%`;
            hp.style.cssText = "background:#2a1a1a;padding:0 4px;border-radius:3px;color:#ffb0b0;";
            info.appendChild(hp);
            const mp = document.createElement("span");
            mp.textContent = `MP ${rule.minManaPercent}‑${rule.maxManaPercent}%`;
            mp.style.cssText = "background:#1a1a2a;padding:0 4px;border-radius:3px;color:#b0b0ff;";
            info.appendChild(mp); row.appendChild(info);
            const editBtn = document.createElement("button");
            editBtn.type = "button"; editBtn.className = "mb-small-button"; editBtn.textContent = "Edit";
            editBtn.style.cssText = "width:auto;padding:2px 8px;";
            editBtn.addEventListener("click", () => {
                healEditIndex = index; setHealRuleFormValues(bot.heal.config.healRules[index]);
                document.getElementById("minibia-bot-heal-editor").hidden=false;
                document.getElementById("minibia-bot-heal-save").textContent = "Update Rule";
            });
            row.appendChild(editBtn);
            const removeBtn = document.createElement("button");
            removeBtn.type = "button"; removeBtn.className = "mb-small-button"; removeBtn.textContent = "\u2715"; removeBtn.title = "Remove rule";
            removeBtn.style.cssText = "width:24px;padding:2px;background:#5a2020;color:#ff8888;border-color:#883030;";
            removeBtn.addEventListener("click", () => {
                const current = bot.heal.config.healRules.slice(); current.splice(index, 1);
                bot.heal.updateConfig({ healRules: current });
                refreshHealRules(); refreshAutoHealStatus(); clearHealRuleForm();
            });
            row.appendChild(removeBtn); list.appendChild(row);
        });
    }

    function saveHealRule() {
        const values = getHealRuleFormValues();
        if (!["hotbar", "spell", "item"].includes(values.source)) return setHealRuleError("Choose a healing action.");
        if (values.source === "hotbar" && (!Number.isInteger(values.slot) || values.slot < 1 || values.slot > 12)) return setHealRuleError("Hotbar slot must be 1–12.");
        if (values.source === "spell" && !values.spellWords) return setHealRuleError("Enter a spell name or spell words.");
        if (values.source === "spell" && (!Number.isFinite(values.manaCost) || values.manaCost <= 0)) return setHealRuleError("Enter a mana cost greater than 0.");
        if (values.source === "item" && !Object.hasOwn(bot.heal.itemTypes, values.item)) return setHealRuleError("Choose IH, UH, Life Fluid or Mana Fluid.");
        if ([values.minHp, values.maxHp, values.minMana, values.maxMana].some(n => !Number.isFinite(n) || n < 0 || n > 100)) return setHealRuleError("HP and MP percentages must be 0–100.");
        if (values.minHp > values.maxHp) return setHealRuleError("Min HP cannot be greater than Max HP.");
        if (values.minMana > values.maxMana) return setHealRuleError("Min MP cannot be greater than Max MP.");
        const rules = bot.heal.config.healRules.slice();
        const old = healEditIndex == null ? null : rules[healEditIndex];
        const newRule = {
            enabled: old?.enabled !== false,
            source: values.source,condition:values.condition,
            skipWhileTargeting: values.skipWhileTargeting,
            ...(old?.cooldownMs!=null?{cooldownMs:old.cooldownMs}:{}),
            ...(old?.legacyCooldownSlot && values.source === old.source ? { legacyCooldownSlot: old.legacyCooldownSlot } : {}),
            slot: values.source === "hotbar" ? values.slot : old?.slot || 1,
            spellWords: values.source === "spell" ? bot.heal.resolveSpell(values.spellWords).words : "",
            manaCost: values.manaCost, item: values.item,
            minHpPercent: values.minHp, maxHpPercent: values.maxHp,
            minManaPercent: values.minMana, maxManaPercent: values.maxMana,
        };
        if (healEditIndex !== null) rules[healEditIndex] = newRule;
        else rules.push(newRule);
        bot.heal.updateConfig({ healRules: rules });
        refreshHealRules(); refreshAutoHealStatus(); clearHealRuleForm();
    }

    function refreshAutoHealStatus() {
        const toggle = document.getElementById("minibia-bot-auto-heal-enabled");
        if (toggle) toggle.checked = !!bot.heal?.status?.().running;
    }

    // ---- RUNE SHOOTER UI ----
    let runeShooterEditIndex = null;

    function clearRuneShooterRuleForm() {
        const type = document.getElementById("minibia-bot-rune-shooter-type");
        const count = document.getElementById("minibia-bot-rune-shooter-count");
        const save = document.getElementById("minibia-bot-rune-shooter-save");
        if (type) type.value = "sd";
        if (count) count.value = "1";
        const names = document.getElementById("minibia-bot-rune-shooter-mob-names");
        if (names) names.value = "";
        if (save) save.textContent = "Add Rule";
        runeShooterEditIndex = null;
    }

    function setRuneShooterRuleForm(rule, index) {
        const type = document.getElementById("minibia-bot-rune-shooter-type");
        const count = document.getElementById("minibia-bot-rune-shooter-count");
        const save = document.getElementById("minibia-bot-rune-shooter-save");
        if (type) type.value = rule?.rune || "sd";
        if (count) count.value = String(rule?.minCreatures ?? 1);
        const names = document.getElementById("minibia-bot-rune-shooter-mob-names");
        if (names) names.value = (rule?.mobNames || []).join(", ");
        if (save) save.textContent = "Update Rule";
        runeShooterEditIndex = index;
    }

    function refreshRuneShooterStatus() {
        const toggle = document.getElementById("minibia-bot-rune-shooter-enabled");
        const list = document.getElementById("minibia-bot-rune-shooter-rules-list");
        const label = document.getElementById("minibia-bot-rune-shooter-status");
        const status = bot.runeShooter?.status?.();
        const currentOnly=document.getElementById("minibia-bot-targeting-rune-current-only");
        if (currentOnly) currentOnly.checked=status?.config?.currentTargetOnly===true;

        if (toggle && document.activeElement !== toggle)
            toggle.checked = !!status?.running;

        if (label) {
            const last = status?.lastRuneLabel
                ? `${status.lastRuneLabel}${status.lastHitCount ? ` (${status.lastHitCount} hit${status.lastHitCount === 1 ? "" : "s"})` : ""}`
                : "none";
            const cd = Number(status?.runeCooldownRemainingMs || 0);
            label.textContent =
                `Visible monsters: ${status?.visibleMonsterCount ?? 0} | Last: ${last}` +
                (cd > 0 ? ` | Rune CD ${(cd / 1000).toFixed(1)}s` : "");
        }

        if (!list) return;
        const rules = status?.config?.rules || bot.runeShooter?.config?.rules || [];
        const supplies = status?.supplies || {};
        const defs = bot.runeShooter?.getRuneTypes?.() || [];
        const byKey = new Map(defs.map(def => [def.key, def]));

        list.innerHTML = "";
        if (!rules.length) {
            const empty = document.createElement("div");
            empty.className = "mb-small-note";
            empty.textContent = "No rune shooter rules configured.";
            list.appendChild(empty);
            return;
        }

        rules.forEach((rule, index) => {
            const def = byKey.get(rule.rune);
            const supply = supplies[rule.rune];

            const row = document.createElement("div");
            row.className = "mb-list-row";
            row.style.cssText = "display:grid;grid-template-columns:1fr auto auto;gap:6px;align-items:center;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.08);";

            const info = document.createElement("div");
            info.style.cssText = "display:flex;flex-wrap:wrap;gap:5px;align-items:center;font-size:11px;";

            const rune = document.createElement("span");
            rune.textContent = def?.short || String(rule.rune || "Rune").toUpperCase();
            rune.style.cssText = "font-weight:bold;color:#e9d39b;";
            info.appendChild(rune);

            const count = document.createElement("span");
            count.textContent = `≥ ${rule.minCreatures} creature${rule.minCreatures === 1 ? "" : "s"}`;
            count.style.cssText = "background:#202a1a;padding:0 4px;border-radius:3px;color:#c8efb0;";
            info.appendChild(count);

            const mode = document.createElement("span");
            mode.textContent = def?.mode === "aoe" ? "AoE auto-aim" : "single target";
            mode.style.cssText = "opacity:0.72;";
            info.appendChild(mode);
            const names = document.createElement("span");
            names.textContent = rule.mobNames?.length ? `Mobs: ${rule.mobNames.join(", ")}` : "Any mob";
            names.style.cssText = "color:#e9d39b;";
            info.appendChild(names);

            const qty = document.createElement("span");
            qty.textContent = supply?.known ? `×${supply.count}` : "×?";
            qty.style.cssText = "color:#9fcfff;";
            qty.title = def ? `${def.label} CID ${def.itemId}${supply?.fresh === false ? " (count may be stale)" : ""}` : "";
            info.appendChild(qty);

            row.appendChild(info);

            const edit = document.createElement("button");
            edit.type = "button";
            edit.className = "mb-small-button";
            edit.textContent = "Edit";
            edit.style.cssText = "width:auto;padding:2px 8px;";
            edit.addEventListener("click", () => setRuneShooterRuleForm(rule, index));
            row.appendChild(edit);

            const remove = document.createElement("button");
            remove.type = "button";
            remove.className = "mb-small-button";
            remove.textContent = "✕";
            remove.title = "Remove rule";
            remove.style.cssText = "width:24px;padding:2px;background:#5a2020;color:#ff8888;border-color:#883030;";
            remove.addEventListener("click", () => {
                const current = (bot.runeShooter?.config?.rules || []).map(entry => ({...entry}));
                current.splice(index, 1);
                bot.runeShooter?.updateConfig?.({ rules: current });
                clearRuneShooterRuleForm();
                refreshRuneShooterStatus();
            });
            row.appendChild(remove);

            list.appendChild(row);
        });
    }

    function saveRuneShooterRule() {
        const type = document.getElementById("minibia-bot-rune-shooter-type");
        const count = document.getElementById("minibia-bot-rune-shooter-count");
        const rune = String(type?.value || "sd");
        const minCreatures = Math.max(1, Math.min(30, Math.trunc(Number(count?.value) || 1)));
        if (count) count.value = String(minCreatures);

        const rules = (bot.runeShooter?.config?.rules || []).map(entry => ({...entry}));
        const mobNames = String(document.getElementById("minibia-bot-rune-shooter-mob-names")?.value || "")
            .split(/[,;\n]+/).map(name => name.trim()).filter(Boolean);
        const next = { rune, minCreatures, mobNames };

        if (runeShooterEditIndex !== null && runeShooterEditIndex >= 0 && runeShooterEditIndex < rules.length)
            rules[runeShooterEditIndex] = next;
        else
            rules.push(next);

        bot.runeShooter?.updateConfig?.({ rules });
        clearRuneShooterRuleForm();
        refreshRuneShooterStatus();
    }

    // ---- AUTO ATTACK STATUS ----
    function refreshAutoAttackStatus() {
        const status = bot.attack?.status?.();
        const attackConfig = bot.attack?.getBaseConfig?.() || status?.config || bot.attack?.config || {};
        const mode=bot.combatRules?.getDefaultMode?.(attackConfig) || 'melee';
        const modeSelect=document.getElementById('minibia-bot-targeting-default-mode');
        if(modeSelect && document.activeElement!==modeSelect)modeSelect.value=mode;
        const custom=modeSelect?.querySelector('option[value="custom"]');if(custom)custom.hidden=mode!=='custom';
        const positionSelect=document.getElementById('minibia-bot-targeting-default-position');
        if(positionSelect && document.activeElement!==positionSelect)positionSelect.value=attackConfig.keepFront?'front':attackConfig.keepDiagonal?'diagonal':'any';
        const kiteField=document.getElementById('minibia-bot-targeting-kite-field');if(kiteField)kiteField.style.display=['kite','kite-lure','custom'].includes(mode)?'':'none';
        bot.combatRules?.refreshStatus?.();
        const inputs = {
            enabled: document.getElementById("minibia-bot-auto-attack-enabled"),
            melee: document.getElementById("minibia-bot-auto-attack-melee"),
            hotkey: document.getElementById("minibia-bot-auto-attack-hotkey"),
            maxDist: document.getElementById("minibia-bot-auto-attack-maxdist"),
            offscreenHunt: document.getElementById("minibia-bot-auto-attack-offscreen-hunt"),
            alphaHunter: document.getElementById("minibia-bot-auto-attack-alpha-hunter"),
            offscreenHuntRange: document.getElementById("minibia-bot-auto-attack-offscreen-hunt-range"),
            offscreenLootFirst: document.getElementById("minibia-bot-auto-attack-offscreen-loot-first"),
            antiKS: document.getElementById("minibia-bot-auto-attack-antiks"),
            antiKSSelf: document.getElementById("minibia-bot-auto-attack-antiks-self"),
            antiKSOther: document.getElementById("minibia-bot-auto-attack-antiks-other"),
            lure: document.getElementById("minibia-bot-auto-attack-lure"),
            lureCount: document.getElementById("minibia-bot-auto-attack-lure-count"),
            lureRadius: document.getElementById("minibia-bot-auto-attack-lure-radius"),
            lureOffscreenPull: document.getElementById("minibia-bot-auto-attack-lure-offscreen-pull"),
            lureOffscreenPullRange: document.getElementById("minibia-bot-auto-attack-lure-offscreen-pull-range"),
            lureSmart: document.getElementById("minibia-bot-auto-attack-lure-smart"),
            lurePreserveHp: document.getElementById("minibia-bot-auto-attack-lure-preserve-hp"),
            lureLastHp: document.getElementById("minibia-bot-auto-attack-lure-last-hp"),
            lureLastMode: document.getElementById("minibia-bot-auto-attack-lure-last-mode"),
            lureStatus: document.getElementById("minibia-bot-auto-attack-lure-status"),
        };
        const kiteToggle = document.getElementById("minibia-bot-auto-attack-kite");
        const idealDistInput = document.getElementById("minibia-bot-auto-attack-ideal-dist");
        const keepDiagonalToggle = document.getElementById("minibia-bot-auto-attack-keep-diagonal");
        const keepFrontToggle = document.getElementById("minibia-bot-auto-attack-keep-front");
        if(keepFrontToggle && document.activeElement!==keepFrontToggle)keepFrontToggle.checked=attackConfig.keepFront===true;
        const clientChaseStatusToggle = document.getElementById("minibia-bot-auto-attack-client-chase");
        if (keepDiagonalToggle && document.activeElement !== keepDiagonalToggle) {
            keepDiagonalToggle.checked = attackConfig.keepDiagonal || false;
        }
        if (kiteToggle)
            kiteToggle.checked = !!attackConfig.kiteMode;

        if (clientChaseStatusToggle) {
            clientChaseStatusToggle.checked =
                !!attackConfig.useClientChase &&
                !attackConfig.kiteMode;
            clientChaseStatusToggle.disabled =
                !!attackConfig.kiteMode;
            clientChaseStatusToggle.title =
                attackConfig.kiteMode
                    ? "Client Chase is automatically disabled while Kite is enabled."
                    : "";
        }

        if (idealDistInput && document.activeElement !== idealDistInput) {
            idealDistInput.value = attackConfig.idealDistance ?? 3;
        }
        if (inputs.enabled)
            inputs.enabled.checked = !!status?.running;
        if (inputs.melee)
            inputs.melee.checked = attackConfig.meleeMode !== false;
        if (inputs.hotkey && document.activeElement !== inputs.hotkey) {
            inputs.hotkey.value = String(attackConfig.targetHotbarSlot ?? 3);
        }
        if (inputs.maxDist && document.activeElement !== inputs.maxDist) {
            inputs.maxDist.value = attackConfig.maxTargetDistance ?? 5;
        }
        if (inputs.offscreenHunt) {
            inputs.offscreenHunt.checked =
                attackConfig.offscreenHuntEnabled === true;
        }
        if (inputs.alphaHunter)
            inputs.alphaHunter.checked=attackConfig.alphaHunterEnabled===true;
        if (inputs.offscreenLootFirst) {
            inputs.offscreenLootFirst.checked=attackConfig.offscreenHuntLootFirst===true;
            inputs.offscreenLootFirst.disabled=attackConfig.offscreenHuntEnabled!==true && attackConfig.alphaHunterEnabled!==true;
        }
        if (
            inputs.offscreenHuntRange &&
            document.activeElement !== inputs.offscreenHuntRange
        ) {
            inputs.offscreenHuntRange.value =
                attackConfig.offscreenHuntRange ?? 20;
        }
        if (inputs.antiKS)
            inputs.antiKS.checked = attackConfig.antiKSEnabled !== false;
        if (inputs.antiKSSelf && document.activeElement !== inputs.antiKSSelf) {
            inputs.antiKSSelf.value = attackConfig.antiKSSelfRange ?? 2;
        }
        if (inputs.antiKSOther && document.activeElement !== inputs.antiKSOther) {
            inputs.antiKSOther.value = attackConfig.antiKSOtherRange ?? 2;
        }
        if (inputs.lure)
            inputs.lure.checked = attackConfig.lureMode === true;
        if (inputs.lureCount && document.activeElement !== inputs.lureCount) {
            inputs.lureCount.value = attackConfig.lureMobThreshold ?? 3;
        }
        if (inputs.lureRadius && document.activeElement !== inputs.lureRadius) {
            inputs.lureRadius.value = attackConfig.lureRadius ?? 5;
        }
        if (inputs.lureOffscreenPull) {
            inputs.lureOffscreenPull.checked =
                attackConfig.lureOffscreenPullEnabled === true || attackConfig.kiteLureMode === true;
            inputs.lureOffscreenPull.disabled = attackConfig.kiteLureMode === true;
            inputs.lureOffscreenPull.title = attackConfig.kiteLureMode ? "Automatic in Kite Lure mode" : "Pull nearby known monsters off screen";
        }
        if (
            inputs.lureOffscreenPullRange &&
            document.activeElement !== inputs.lureOffscreenPullRange
        ) {
            inputs.lureOffscreenPullRange.value =
                attackConfig.lureOffscreenPullRange ?? 10;
        }
        if (inputs.lureSmart)
            inputs.lureSmart.checked = attackConfig.lureSmartTargeting !== false;
        if (inputs.lurePreserveHp && document.activeElement !== inputs.lurePreserveHp) {
            inputs.lurePreserveHp.value = attackConfig.lurePreserveHpPct ?? 30;
            inputs.lurePreserveHp.disabled = attackConfig.lureSmartTargeting === false;
        }
        if (inputs.lureLastHp && document.activeElement !== inputs.lureLastHp) {
            inputs.lureLastHp.value = attackConfig.lureLastMobHpPct ?? 20;
        }
        if (inputs.lureLastMode && document.activeElement !== inputs.lureLastMode) {
            inputs.lureLastMode.value =
                String(attackConfig.lureLastMobMode || "slow").toLowerCase() === "kill"
                    ? "kill"
                    : "slow";
        }
        if (inputs.lureStatus) {
            if (attackConfig.kiteLureMode) {
                inputs.lureStatus.textContent = `Kite Lure · ${status?.kiteLurePhase === "pulling" ? "gathering nearby monsters" : "keeping pack at kite distance"}`;
            } else if (!attackConfig.lureMode) {
                inputs.lureStatus.textContent = "Lure: off";
            } else if (status?.lureActive) {
                const wp = status.lureWaypointIndex != null
                    ? ` → WP ${status.lureWaypointIndex + 1}`
                    : "";
                if (status.lureOffscreenPullActive) {
                    const name = status.lureOffscreenPullTargetName
                        ? ` • ${status.lureOffscreenPullTargetName}`
                        : "";
                    const dist = Number.isFinite(Number(status.lureOffscreenPullLastDistance))
                        ? ` ${Math.round(Number(status.lureOffscreenPullLastDistance))}t`
                        : "";
                    inputs.lureStatus.textContent =
                        `Off-screen Pull${dist}${name} • bringing mob into @${status.lureRadius}t`;
                } else if (status.preferredAccessBlocked) {
                    const pref = status.preferredAccess?.preferredName
                        ? ` • ${status.preferredAccess.preferredName}`
                        : "";
                    const blockers = status.preferredAccess?.blockerIds?.length || 0;
                    inputs.lureStatus.textContent =
                        `Clearing ${blockers} blocker${blockers === 1 ? "" : "s"} for preferred${pref}`;
                } else if (status.lureEmergencyClear?.active) {
                    const name = status.lureEmergencyClear.name
                        ? ` • ${status.lureEmergencyClear.name}`
                        : "";
                    inputs.lureStatus.textContent =
                        `Escape clear${name} • route blocked`;
                } else if (status.lurePreferredPending) {
                    const name = status.lurePreferredTrackedName
                        ? ` • ${status.lurePreferredTrackedName}`
                        : "";
                    const dist = Number.isFinite(Number(status.lurePreferredTrackedDistance))
                        ? ` ${Math.round(Number(status.lurePreferredTrackedDistance))}t`
                        : "";
                    inputs.lureStatus.textContent =
                        `Preferred ahead${dist}${name} • soft attacking pack`;
                } else if (status.lureLastMobActive) {
                    const hp = Number.isFinite(Number(status.lureLastMobHealthPct))
                        ? Math.round(Number(status.lureLastMobHealthPct))
                        : "?";
                    const name = status.lureLastMobName
                        ? ` • ${status.lureLastMobName}`
                        : "";
                    inputs.lureStatus.textContent =
                        status.lureLastMobMode === "kill"
                            ? `Finishing last mob ${hp}%${name}`
                            : `Slow-finishing last mob ${hp}%${name}`;
                } else if (status.lureCrowdBlocked) {
                    inputs.lureStatus.textContent =
                        `Pack blocking corridor • holding (${status.lureCrowdBlockerCount} mobs)`;
                } else if (status.lureMovementHeld) {
                    const mob = status.lureLeashMobName
                        ? ` • ${status.lureLeashMobName}`
                        : "";
                    const predictive =
                        status.lureLeashReason === "trailing mob losing ground"
                            ? "Catching lagging pack"
                            : "Waiting for pack";
                    inputs.lureStatus.textContent =
                        `${predictive} ${status.lureMobCount}/${status.lureMobThreshold} @${status.lureRadius}t${mob}`;
                } else {
                    const smart = status.lureSmartTargeting
                        ? ` • smart>${Math.round(status.lurePreserveHpPct)}%`
                        : "";
                    inputs.lureStatus.textContent =
                        `Luring + attacking ${status.lureMobCount}/${status.lureMobThreshold} @${status.lureRadius}t${wp}${smart}`;
                }
            } else {
                inputs.lureStatus.textContent =
                    `Lure: ${status?.lureReason || "ready"} (${status?.lureMobCount ?? 0}/${attackConfig.lureMobThreshold ?? 3} @${attackConfig.lureRadius ?? 5}t)`;
            }
        }
        refreshAutoAttackPreferredStatus();
        if (typeof refreshTitlebarRunIndicators === "function")
            refreshTitlebarRunIndicators();
    }

