    function refreshEquipRingStatus() {
        const status = bot.equipRing?.status?.();
        const toggle = document.getElementById("minibia-bot-equip-ring-enabled");
        if (toggle) toggle.checked = !!status?.running;
        const idInput = document.getElementById("minibia-bot-equip-ring-id");
        if (idInput && document.activeElement !== idInput)
            idInput.value = bot.equipRing?.config?.ringId || "";
        const selectButton = document.getElementById("minibia-bot-equip-ring-select");
        if (selectButton) {
            const selecting = !!status?.selectingRing;
            selectButton.setAttribute("aria-pressed", selecting ? "true" : "false");
            selectButton.title = selecting
                ? "Selecting ring: click a ring in an open backpack/equipment slot. Click 🔍 again to cancel."
                : "Click, then click a ring in an open backpack or equipment slot";
        }
        const countLabel = document.getElementById("minibia-bot-equip-ring-count");
        if (countLabel) {
            const ringId = Number(status?.selectedRingId || bot.equipRing?.config?.ringId || 0);
            if (!ringId) {
                countLabel.textContent = "";
                countLabel.title = "Set a ring ID to use the server-side item count.";
            } else if (status?.gates?.serverCountFresh) {
                countLabel.textContent = `×${status.gates.serverCount ?? 0}`;
                countLabel.title = "Server item count (full inventory, including closed backpacks).";
            } else {
                countLabel.textContent = "×?";
                countLabel.title = "Waiting for the server item count.";
            }
        }
        const unequip98Toggle = document.getElementById("minibia-bot-equip-ring-unequip-98");
        if (unequip98Toggle) unequip98Toggle.checked = !!bot.equipRing?.config?.unequipRingAt98;
        const cycle=bot.equipRing?.config || {};
        for(const [suffix,key] of [["low","cycleLow"],["high","cycleHigh"],["id","cycleRingId"]]){
            const input=document.getElementById(`minibia-bot-ring-cycle-${suffix}`);
            if(input && document.activeElement!==input)input.value=cycle[key] || (suffix==="id"?"":0);
        }
        const cycleToggle=document.getElementById("minibia-bot-ring-cycle-enabled");
        if(cycleToggle)cycleToggle.checked=cycle.manaCycleEnabled===true;
        const cycleOn=cycle.manaCycleEnabled===true;
        const normalRow=document.getElementById("minibia-bot-ring-normal-row");
        if(normalRow)normalRow.hidden=!cycleOn;
        const lowField=document.getElementById("minibia-bot-ring-low-field");
        if(lowField)lowField.hidden=!cycleOn;
        const primaryLabel=document.getElementById("minibia-bot-ring-primary-label");
        if(primaryLabel)primaryLabel.textContent=cycleOn?"Recovery":"Ring";
        if(idInput)idInput.placeholder=cycleOn?"Ring ID":"Any ring";
        if(unequip98Toggle)unequip98Toggle.disabled=cycle.manaCycleEnabled===true;
        const cycleStatus=document.getElementById("minibia-bot-ring-cycle-status");
        if(cycleStatus){
            const defs=window.gameClient?.itemDefinitionsByCid || {};
            const ringName=id=>defs[id]?.properties?.name || (id?`Ring ${id}`:"Select ring");
            const incomplete=cycleOn && !(cycle.ringId && cycle.cycleRingId);
            cycleStatus.hidden=!incomplete;
            cycleStatus.textContent=incomplete?"Select both rings to start the cycle.":"";
            if(idInput && cycle.ringId)idInput.title=ringName(cycle.ringId);
            const normalInput=document.getElementById("minibia-bot-ring-cycle-id");
            if(normalInput && cycle.cycleRingId)normalInput.title=ringName(cycle.cycleRingId);
        }
        const warnToggle = document.getElementById("minibia-bot-equip-ring-warn");
        if (warnToggle) warnToggle.checked = !!bot.equipRing?.config?.warnMissingRing;
    }

    function refreshTalkStatus() {
        const toggle = document.getElementById("minibia-bot-talk-enabled");
        const label = document.getElementById("minibia-bot-talk-status");
        const status = bot.talk?.status?.();

        // Only update checkbox if it's not currently focused (to avoid flicker)
        if (toggle && document.activeElement !== toggle) {
            toggle.checked = !!status?.running;
        }

        if (label) {
            if (!status?.config?.apiKey) {
                label.textContent = "Status: API key missing";
            } else if (status?.pending) {
                label.textContent = "Status: generating";
            } else if (status?.running) {
                label.textContent = "Status: listening to Default";
            } else {
                label.textContent = "Status: idle";
            }
        }
    }

